import{_ as e,o as t,c as r,ae as o}from"./chunks/framework.DFTT1zkb.js";const m=JSON.parse('{"title":"交通出行","description":"","frontmatter":{},"headers":[],"relativePath":"begin/transport.md","filePath":"begin/transport.md"}'),i={name:"begin/transport.md"};function l(p,a,n,s,c,d){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="交通出行" tabindex="-1">交通出行 <a class="header-anchor" href="#交通出行" aria-label="Permalink to &quot;交通出行&quot;">​</a></h1><h2 id="动车-高铁-火车" tabindex="-1">动车 / 高铁 / 火车 <a class="header-anchor" href="#动车-高铁-火车" aria-label="Permalink to &quot;动车 / 高铁 / 火车&quot;">​</a></h2><p>石家庄市有多个动车站（高铁站），但只有石家庄站和石家庄东站是出站无缝衔接地铁站的，如无其他必要原因，推荐选择石家庄站上下车</p><p>石家庄站(距学校21km)为普通火车+高铁站，石家庄东站(距学校10km)为高铁站</p><p>买票认准 12306，别忘了勾选上学生票选项</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>12306 从未与任何第三方平台合作，也没有将票额分配给任何第三方平台进行发售。铁路 12306 平台才是铁路部门唯一的官方售票渠道</p></div><h3 id="学生票优惠" tabindex="-1">学生票优惠 <a class="header-anchor" href="#学生票优惠" aria-label="Permalink to &quot;学生票优惠&quot;">​</a></h3><p><mark>普速火车硬座半价，动车高铁二等座 75 折</mark></p><ul><li>没有学生证的大一新生可以先用录取通知书在 12306 上验明学生资质并购买学生票，通过录取通知书即可证明学生身份</li><li>后续等学生证下发后，每年有 4 次的优惠次数（于每年 10 月 1 日重置），但仅限于学生证中登记的居住地与学校之间的往返</li></ul><h3 id="抢票攻略" tabindex="-1">抢票攻略 <a class="header-anchor" href="#抢票攻略" aria-label="Permalink to &quot;抢票攻略&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><strong>抢票难度</strong></p><p>国庆 &gt; 五一 ≈ 清明 ≈ 中秋 &gt; 端午 ≫ 放假 ≈ 开学</p><p>大部分情况下，开学和放假的车票几乎不需要抢，很容易就可以买到</p></div><p>车票于开车日期前 14 天开始售卖，每个站点的开票时间有所不同。</p><p>你可以提前在第三方 App（携程、同程等） 上查看未来超过 14 天的发车情况和放票时间。使用第三方软件购票时，推荐使用 <mark>登录 12306 账号</mark> 功能购票避免加价和个人信息泄露</p><p>除此之外，第三方平台还可能根据实际情况推出以下等功能，这在不方便监控余票时很好用</p><h4 id="买长乘短" tabindex="-1">买长乘短 <a class="header-anchor" href="#买长乘短" aria-label="Permalink to &quot;买长乘短&quot;">​</a></h4><p>购票区间长于实际乘车区间，但这可能造成额外花费</p><h4 id="中转" tabindex="-1">中转 <a class="header-anchor" href="#中转" aria-label="Permalink to &quot;中转&quot;">​</a></h4><p><code>A → C</code>的直达车票票拆为<code>A → B</code>和<code>B → C</code>购买，但是中途可能需要换座位或列车</p><h4 id="自动候补" tabindex="-1">自动候补 <a class="header-anchor" href="#自动候补" aria-label="Permalink to &quot;自动候补&quot;">​</a></h4><p>当所购买的票售罄后自动提交候补，无法完全保证候补成功</p><h2 id="机场" tabindex="-1">机场 <a class="header-anchor" href="#机场" aria-label="Permalink to &quot;机场&quot;">​</a></h2><p>距离学校最近的为石家庄正定国际机场(17km)</p>',22)])])}const u=e(i,[["render",l]]);export{m as __pageData,u as default};
